DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 056", "old_status": "worked_needs_crop", "status": "ready", "question_id": "0a2a4c1a-a3df-558f-87e1-4ca468bbca65", "stem": "The table classifies all 30 rabbits on a farm. Given that a randomly selected rabbit is not white, what is the probability that it is big?", "choices": [{"key": "A", "text": "3/5"}, {"key": "B", "text": "3/7"}, {"key": "C", "text": "3/8"}, {"key": "D", "text": "16/30"}], "type": "mcq", "correct": "C", "explanation": "There are 4 + 6 + 2 + 4 = 16 nonwhite rabbits. Of those, 2 + 4 = 6 are big. The conditional probability is 6/16 = 3/8.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 190 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 190, "extra_sources": [], "assets": {"html": "<table><thead><tr><th>Size</th><th>White</th><th>Brown</th><th>Gray</th></tr></thead><tbody><tr><td>Small</td><td>4</td><td>4</td><td>6</td></tr><tr><td>Big</td><td>10</td><td>2</td><td>4</td></tr></tbody></table>"}}, {"id": "clean:HOA 051", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "8843e996-69f9-5617-9816-e646191f1c04", "stem": "The table gives scores out of 10 for four players over five rounds. Which player was most consistent, meaning that the scores had the smallest standard deviation?", "choices": [{"key": "A", "text": "Mark"}, {"key": "B", "text": "Diego"}, {"key": "C", "text": "Toni"}, {"key": "D", "text": "Tyler"}], "type": "mcq", "correct": "D", "explanation": "The standard deviations are approximately 2.61 for Mark, 1.85 for Diego, 2.28 for Toni, and 0.75 for Tyler. Tyler has the smallest spread and is the most consistent. Computing from Tyler’s scores 8, 7, 6, 7, 8 gives population variance 0.56 and standard deviation √0.56 ≈ 0.748.", "topic": "Statistics, Probability & Data Analysis", "note": "Reunited HOA 051 page 36 with PSD 061 page 194, visually verified the complete score table and recomputed the standard deviations.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 36, "extra_sources": [], "assets": {"html": "<table><thead><tr><th>Round</th><th>Diego</th><th>Mark</th><th>Tyler</th><th>Toni</th></tr></thead><tbody><tr><td>1</td><td>7</td><td>3</td><td>8</td><td>10</td></tr><tr><td>2</td><td>5</td><td>10</td><td>7</td><td>4</td></tr><tr><td>3</td><td>8</td><td>9</td><td>6</td><td>9</td></tr><tr><td>4</td><td>9</td><td>5</td><td>7</td><td>10</td></tr><tr><td>5</td><td>4</td><td>8</td><td>8</td><td>7</td></tr><tr><td>Standard deviation</td><td>1.85</td><td>2.61</td><td>0.75</td><td>2.28</td></tr></tbody></table>"}}, {"id": "clean:PSD 064", "old_status": "worked_needs_crop", "status": "ready", "question_id": "625c0344-7b5d-5a9d-8b76-6f938d573090", "stem": "The table summarizes the favorite subjects of 350 students. Among primary students, which subject has the lowest percentage of supporters?", "choices": [{"key": "A", "text": "Math"}, {"key": "B", "text": "English"}, {"key": "C", "text": "Science"}, {"key": "D", "text": "History"}], "type": "mcq", "correct": "D", "explanation": "All four percentages use the same denominator, 125 primary students. History has the smallest count, 10, giving 10/125 = 8%; the other counts are 65, 35, and 15.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 196 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 196, "extra_sources": [], "assets": {"html": "<table><thead><tr><th>Subject</th><th>Primary</th><th>Secondary</th><th>Tertiary</th><th>Total</th></tr></thead><tbody><tr><td>Math</td><td>65</td><td>80</td><td>30</td><td>175</td></tr><tr><td>English</td><td>35</td><td>55</td><td>10</td><td>100</td></tr><tr><td>Science</td><td>15</td><td>10</td><td>25</td><td>50</td></tr><tr><td>History</td><td>10</td><td>5</td><td>10</td><td>25</td></tr><tr><td>Total</td><td>125</td><td>150</td><td>75</td><td>350</td></tr></tbody></table>"}}, {"id": "clean:PSD 066", "old_status": "worked_needs_crop", "status": "ready", "question_id": "04c16fc4-9bdd-5314-ab62-6726bda9e78b", "stem": "A parliament consists of 35% Democrats, 20% Conservatives, 30% Republicans, and 27 Labor members. How many more Democrats are there than Conservatives?", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "18"}, {"key": "C", "text": "27"}, {"key": "D", "text": "36"}], "type": "mcq", "correct": "C", "explanation": "Labor represents the remaining 100 − 35 − 20 − 30 = 15%. The Democrat–Conservative difference is also 35% − 20% = 15%, so it equals the 27 Labor members.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 198 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 198, "extra_sources": []}, {"id": "clean:PSD 068", "old_status": "worked_needs_crop", "status": "ready", "question_id": "567d41f5-3907-54dc-8785-0d007ff45073", "stem": "A painter averages 1.2 walls per hour. A villa has 18 rooms averaging 5.4 walls each. How much active painting time is needed, using 24 hours per day?", "choices": [{"key": "A", "text": "2 days, 18 hours"}, {"key": "B", "text": "3 days"}, {"key": "C", "text": "3 days, 9 hours"}, {"key": "D", "text": "3 days, 18 hours"}], "type": "mcq", "correct": "C", "explanation": "The total is 18 × 5.4 = 97.2 walls. At 1.2 walls per hour, the time is 97.2/1.2 = 81 hours = 3 × 24 + 9 hours, or 3 days and 9 hours.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 199 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 199, "extra_sources": []}, {"id": "clean:PSD 147", "old_status": "worked_missing_choice", "status": "ready", "question_id": "0a5db211-7ad8-5b04-b0f2-f74d0a8fb6ae", "stem": "How many distinct arrangements can be made using all the letters of PHARMACY?", "choices": [{"key": "A", "text": "40320"}, {"key": "B", "text": "20160"}, {"key": "C", "text": "10900"}, {"key": "D", "text": "10100"}], "type": "mcq", "correct": "B", "explanation": "There are 8 letters with two identical As. Divide the 8! arrangements of labeled letters by 2! for the repeated As: 8!/2! = 20160.", "topic": "Statistics, Probability & Data Analysis", "note": "Restored choices C and D from the start of PSD 148 on the same page 257.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 257, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
